def can_tile(n, r, c):
    cells = set()
    for i in range(r):
        for j in range(n):
            cells.add((i, j))
    for i in range(n):
        for j in range(c):
            cells.add((i, j))

    if len(cells) % 3 != 0:
        return False

    def solve_fast(remaining_cells):
        if not remaining_cells:
            return True
        min_cell = min(remaining_cells)
        i, j = min_cell
        tromino = {(i, j), (i+1, j), (i+1, j+1)}
        if all(cell in remaining_cells for cell in tromino):
            if solve_fast(remaining_cells - tromino):
                return True
        return False

    return solve_fast(frozenset(cells))

