    # Try to tile an r x c block with L-trominoes
    # L-tromino is (i,j), (i+1,j), (i,j+1)
    # This is a small enough problem to use backtracking
    grid = [[False for _ in range(c)] for _ in range(r)]

    def solve(idx):
        if idx == r * c:
            return True
        i, j = divmod(idx, c)
        if grid[i][j]:
            return solve(idx + 1)

