def get_possible_sums_fixed(n, count_n, val_n, count_other, val_other):
    # dp[num_n][last_X] = set of possible sums K
    # count_n is the number of times val_n appears in r_0, ..., r_{n-1}
    # count_other is the number of times val_other appears in r_0, ..., r_{n-1}
    # Note: count_n + count_other = n

    dp = [[set() for _ in range(n // 2 + 1)] for _ in range(count_n + 1)]

    # Initial states for i = 0
    # r_0 = val_n
    if val_n % 2 == 0:
        x0 = val_n // 2
        if x0 <= n // 2:
            dp[1][x0].add(x0)
    # r_0 = val_other
    if val_other % 2 == 0:
        x0 = val_other // 2
        if x0 <= n // 2:
            dp[0][x0].add(x0)

    for i in range(1, n):
        new_dp = [[set() for _ in range(n // 2 + 1)] for _ in range(count_n + 1)]
        for num_n in range(count_n + 1):
            for last_X in range(n // 2 + 1):
                if not dp[num_n][last_X]:
                    continue

                for K in dp[num_n][last_X]:
                    # Try r_i = val_n
                    if num_n + 1 <= count_n:
                        if (val_n - last_X) % 2 == 0:
                            x_i = (val_n - last_X) // 2
                            if 0 <= x_i <= n // 2:
                                new_dp[num_n + 1][x_i].add(K + x_i)

                    # Try r_i = val_other
                    num_other = i - num_n
                    if num_other + 1 <= count_other:
                        if (val_other - last_X) % 2 == 0:
                            x_i = (val_other - last_X) // 2
                            if 0 <= x_i <= n // 2:
                                new_dp[num_n][x_i].add(K + x_i)
        dp = new_dp

    res = set()
    for x in range(n // 2 + 1):
        res.update(dp[count_n][x])
    return res

