def is_tileable_recursive(h, w, coords):
    board = [[False] * w for _ in range(h)]

    def solve():
        # Find the first empty cell
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not board[i][j]:
                    r, c = i, j
                    break
            if r != -1:
                break

        if r == -1:
            return True

        # Try all possible ways to cover (r, c) with the tromino
        # A tromino is a set of 3 relative coords.
        # One of these coords must be (r, c).
        # Let the tromino be {(dr0, dc0), (dr1, dc1), (dr2, dc2)}.
        # If (dr_i, dc_i) is placed at (r, c), the other two cells are:
        # (r + dr_j - dr_i, c + dc_j - dc_i) for j != i.

        for i in range(3):
            dr_i, dc_i = coords[i]
            # The other two cells:
            cells = []
            for j in range(3):
                if i == j: continue
                cells.append((r + coords[j][0] - dr_i, c + coords[j][1] - dc_i))

            # Check if these cells are within bounds and empty
            possible = True
            for rr, cc in cells:
                if not (0 <= rr < h and 0 <= cc < w and not board[rr][cc]):
                    possible = False
                    break

            if possible:
                # Place
                board[r][c] = True
                for rr, cc in cells:
                    board[rr][cc] = True

                if solve():
                    return True

                # Backtrack
                board[r][c] = False
                for rr, cc in cells:
                    board[rr][cc] = False
        return False

    return solve()

